"""Build 20 original MCKO-style literature variants from reviewed public-domain readings.
Input quotations and original questions live in lib/mcko/humanities5/literature-*.json.
"""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'lib/mcko/humanities5'
readings=json.loads((D/'literature-readings.json').read_text());poems=json.loads((D/'literature-poems.json').read_text());works=json.loads((D/'literature-works.json').read_text())
ONE='1 балл — ответ верен; иначе 0. Равнозначный термин допускается.'
SEQ='2 балла — все три соответствия верны; 1 — ошибка или пропуск ровно в одной позиции; 0 — ошибки в двух или трёх позициях.'
TWO='Укажите ровно два номера. 2 балла — оба верны; 1 — один верный и один неверный либо указан только один верный; 0 — нет верных или указано больше двух номеров. Повтор номера не считается вторым ответом.'
def rotate(a,n):n%=len(a);return a[n:]+a[:n]
def numbered(a):return '\n'.join(f'{i+1}) {x}' for i,x in enumerate(a))
def task(n,text,answer,points=1,solution='',**extra):return dict(n=n,text=text,answer=answer,points=points,solution=solution,level='Б',rubric=ONE,**extra)
def single(n,q,options,seed,**extra):
 arr=rotate(list(enumerate(options)),seed);text=q+'\nВыберите один ответ.\n'+numbered([p[1] for p in arr]);a=str(next(i+1 for i,p in enumerate(arr) if p[0]==0))+' — '+options[0]
 return task(n,text,a,**extra)
def match(n,q,pairs,seed,extraOption=None,**extra):
 meanings=list(dict.fromkeys(p[1] for p in pairs));meanings=rotate(meanings,seed)
 if extraOption is not None:meanings.insert(seed%4,extraOption)
 text=q+'\n'+'\n'.join(f'{"АБВ"[i]}) {p[0]}' for i,p in enumerate(pairs))+'\n\n'+numbered(meanings)+'\n\nЗапишите ответ в порядке А, Б, В.'
 if len(set(p[1] for p in pairs))!=len(pairs):text+=' Цифры могут повторяться.'
 elif extraOption is None:text+=' Каждую цифру используйте один раз.'
 else:text+=' Одна характеристика лишняя.'
 answer='; '.join(f'{"АБВ"[i]} — {meanings.index(p[1])+1}' for i,p in enumerate(pairs));t=task(n,text,answer,2,'\n'.join(p[0]+' — '+p[1] for p in pairs),**extra);t['rubric']=SEQ;return t
terms=[
('Как называется действующее лицо литературного произведения?','Герой (персонаж)'),
('Как называется небольшое иносказательное произведение с нравоучением, часто с животными в роли героев?','Басня'),
('Как называется повествовательное произведение с установкой на вымысел, часто с чудесами и волшебными помощниками?','Сказка'),
('Как называется краткое народное изречение с законченным поучительным смыслом, например «Без труда не вытащишь и рыбку из пруда»?','Пословица'),
('Как называется краткое описание предмета или явления, по признакам которого нужно догадаться, о чём идёт речь?','Загадка'),
('Как одним словом называют устное народное творчество?','Фольклор'),
('Как называется образное определение, подчёркивающее выразительный признак предмета?','Эпитет'),
('Как называется сопоставление двух предметов по сходному признаку, часто при помощи слов «как», «словно», «будто»?','Сравнение'),
('Как называется наделение явлений природы человеческими действиями и чувствами?','Олицетворение'),
('Как называется перенос названия по сходству: например, в авторском выражении «золотой костёр заката»?','Метафора'),
('Как называется намеренное художественное преувеличение?','Гипербола'),
('Как называется описание внешности персонажа?','Портрет'),
('Как называется описание природы в художественном произведении?','Пейзаж'),
('Как называется обмен репликами между персонажами?','Диалог'),
('Как называется развёрнутое высказывание одного персонажа, обращённое к слушателям или к самому себе?','Монолог'),
('Как называется последовательность связанных событий, составляющих действие произведения?','Сюжет'),
('Как называется поучительный вывод в басне?','Мораль'),
('Как называют того, от чьего лица ведётся рассказ о событиях в произведении?','Повествователь (рассказчик)'),
('Как называется род литературы, в котором на первом плане чувства и переживания?','Лирика'),
('Как называется добродушное изображение смешного, не направленное на беспощадное обличение?','Юмор')]
second=[
('Как называется речь, не разделённая на стихотворные строки?','Проза'),
('Как называется созвучие окончаний стихотворных строк?','Рифма'),
('Как называется группа стихотворных строк, объединённых ритмом, рифмами и смыслом?','Строфа'),
('Как называется повторяющееся чередование звуковых элементов, создающее мерность стихотворной речи?','Ритм'),
('Как называется начальное событие, с которого развивается основной конфликт сюжета?','Завязка'),
('Как называется наиболее напряжённый момент развития действия?','Кульминация'),
('Как называется завершение основного конфликта в сюжете?','Развязка'),
('Как называется построение произведения, расположение его частей?','Композиция'),
('Как называется противопоставление образов или понятий для усиления выразительности?','Антитеза (противопоставление)'),
('Как называется скрытая насмешка, когда буквальный смысл похвалы противоположен подразумеваемому?','Ирония'),
('Как называется повтор одного и того же слова в художественном тексте?','Лексический повтор'),
('Как называется изображение человеческих качеств через условные образы, например животных в баснях?','Аллегория (иносказание)'),
('Как называется род литературы, произведения которого предназначены прежде всего для постановки на сцене?','Драма'),
('Как называется краткое авторское пояснение в пьесе о действиях или речи персонажей?','Ремарка'),
('Как называется картина домашней обстановки, внутреннего пространства жилища в произведении?','Интерьер'),
('Как называют человека, создавшего литературное произведение?','Автор (писатель)'),
('Как называется герой, через переживания которого раскрывается внутренний мир в лирическом стихотворении?','Лирический герой'),
('Как называется небольшое повествовательное произведение, обычно сосредоточенное на одном или нескольких эпизодах?','Рассказ'),
('Как называется отдельная относительно завершённая часть действия, изображающая одно событие?','Эпизод'),
('Как называется стихотворная строка?','Стих')]
variants=[]
for i,(reading,poem) in enumerate(zip(readings,poems)):
 n=i+1;stage=i//5;tasks=[task(1,terms[i][0]+' Запишите термин.',terms[i][1],solution=terms[i][1]+'.'),task(2,second[i][0]+' Запишите термин.',second[i][1],solution=second[i][1]+'.')]
 word,options=reading['vocab'];tasks.append(single(3,f'Какое значение имеет слово или выражение «{word}» в приведённом тексте?',options,i,reading=reading['title']+'\n\n'+reading['reading'],source=reading['source'],solution='В этом контексте: '+options[0]+'.'))
 pairs=[('«'+phrase+'»',meaning) for phrase,meaning in rotate(reading['devices'],stage)]
 tasks.append(match(4,'Соотнесите цитаты из этого произведения с приёмами или их ролью. Часть цитат может находиться за пределами отрывка задания 3; все необходимые цитаты приведены здесь.',pairs,i))
 work=works[i%5];characters=rotate(work['characters'],stage)[:3]
 pairs=[(c[0],c[2][stage]) for c in characters]
 tasks.append(match(5,'Задание на знание целого произведения: '+work['title']+'. Соотнесите героев и их поступки.',pairs,i+1))
 arr=rotate(list(enumerate(reading['statements'])),i+2);answer=', '.join(str(j+1) for j,x in enumerate(arr) if x[0]<2)
 t=task(6,'Выберите два утверждения, которые соответствуют тексту задания 3.\n'+numbered([x[1] for x in arr]),answer,2,'Верные утверждения: '+reading['statements'][0]+' '+reading['statements'][1]);t['rubric']=TWO;tasks.append(t)
 tasks.append(single(7,poem['question'],poem['options'],i+1,reading=poem['title']+'\n\n'+poem['reading'],source=poem['source'],solution=poem['options'][0]))
 tasks.append(match(8,'Соотнесите цитаты из стихотворного текста задания 7 с приёмами или их выразительной ролью.',[('«'+p+'»',m) for p,m in rotate(poem['devices'],i)],i+2))
 secondWork=works[(i+2)%5];chars=rotate(secondWork['characters'],stage+1)[:3]
 tasks.append(match(9,'Задание на знание целого произведения: '+secondWork['title']+'. Соотнесите героев и их характеристики.',[(c[0],c[1][stage]) for c in chars],i,extraOption=rotate(secondWork['characters'],stage+1)[3][1][stage]))
 tasks.append(match(10,'Вспомните то же произведение: '+secondWork['title']+'. Соотнесите героев с поступками.',[(c[0],c[2][(stage+2)%4]) for c in chars],i+1))
 q,opts,sol=secondWork['questions'][stage];tasks.append(single(11,'По произведению '+secondWork['title']+'. '+q,opts,i+3,solution=sol))
 variants.append(dict(id=n,title=reading['title']+' · '+poem['title'],tasks=tasks))
data=dict(grade=5,subject='literatura',subjectTitle='Литература',year=2026,durationMinutes=45,breakMinutes=5,maxScore=17,instructions='20 авторских тренировок по структуре опубликованной демоверсии МЦКО за май 2026 года. В каждом варианте 11 заданий, максимум 17 баллов. Это не официальные варианты МЦКО. Читайте указанные отрывки и отвечайте письменно. Для заданий 5 и 9–11 требуется знание названных произведений целиком. В заданиях на соответствие записывайте цифры в порядке А, Б, В. Затем откройте ответы и проверьте себя по критериям. Цитаты взяты из произведений классиков; вопросы, подбор заданий и пояснения составлены для тренировки.',variants=variants)
(D/'literatura-5.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');assert len(variants)==20 and all(len(v['tasks'])==11 and sum(t['points'] for t in v['tasks'])==17 for v in variants)
print('Literature:',len(variants),'variants;',sum(len(v['tasks']) for v in variants),'tasks')
